-- Desired database schema for the control plane (source of truth, decision D19).
-- Edit this file, then run `mise run db:diff <name>` to generate a goose migration.
-- Entities are specified in docs/spec/02-domain-model.md. Columns arrive with the
-- milestone that needs them; M1 covers Project, Issue, Run, StepRun and Event.
-- IDs are UUIDv7 generated by the application.

CREATE TABLE projects (
  id                uuid        PRIMARY KEY,
  name              text        NOT NULL UNIQUE,
  -- Issue key prefix (D22): immutable, branch-safe.
  key_prefix        text        NOT NULL UNIQUE CHECK (key_prefix ~ '^[a-z][a-z0-9]{1,9}$'),
  next_issue_number integer     NOT NULL DEFAULT 1 CHECK (next_issue_number >= 1),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE issues (
  id                  uuid        PRIMARY KEY,
  project_id          uuid        NOT NULL REFERENCES projects (id),
  -- Allocated from projects.next_issue_number; key is <key_prefix>-<number> (D22).
  number              integer     NOT NULL CHECK (number >= 1),
  key                 text        NOT NULL UNIQUE,
  -- epic > story > task/bug (D57); the store checks the types and that the parent is in the same project.
  parent_id           uuid        REFERENCES issues (id),
  type                text        NOT NULL CHECK (type IN ('epic', 'story', 'task', 'bug')),
  title               text        NOT NULL,
  spec                text        NOT NULL DEFAULT '',
  acceptance_criteria text[]      NOT NULL DEFAULT '{}',
  status              text        NOT NULL DEFAULT 'draft' CHECK (status IN (
                        'draft', 'refining', 'ready', 'running', 'awaiting_human',
                        'queued', 'merged', 'released', 'failed', 'canceled')),
  priority            integer     NOT NULL DEFAULT 0,
  source_ref          text,
  labels              text[]      NOT NULL DEFAULT '{}',
  created_by          text        NOT NULL,
  created_at          timestamptz NOT NULL DEFAULT now(),
  updated_at          timestamptz NOT NULL DEFAULT now(),
  -- An external issue (e.g. a GitHub issue URL) syncs into at most one Issue per project.
  CONSTRAINT issues_project_source_ref_key UNIQUE (project_id, source_ref),
  CONSTRAINT issues_project_number_key UNIQUE (project_id, number)
);

CREATE INDEX issues_parent_id_idx ON issues (parent_id);

-- The dependency DAG (D57): issue_id waits for depends_on_id. Both are in the same
-- project, and the store rejects edges that close a cycle (counting the hierarchy).
CREATE TABLE issue_dependencies (
  issue_id      uuid        NOT NULL REFERENCES issues (id),
  depends_on_id uuid        NOT NULL REFERENCES issues (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (issue_id, depends_on_id),
  CONSTRAINT issue_dependencies_not_self CHECK (issue_id <> depends_on_id)
);

CREATE INDEX issue_dependencies_depends_on_id_idx ON issue_dependencies (depends_on_id);

CREATE INDEX issues_project_status_idx ON issues (project_id, status);

CREATE TABLE runs (
  id                   uuid        PRIMARY KEY,
  issue_id             uuid        NOT NULL REFERENCES issues (id),
  workflow_snapshot    jsonb       NOT NULL,
  workflow_version     text        NOT NULL,
  -- Stable per issue (e.g. issue-gc-1) and reused by reruns; the Temporal run ID
  -- identifies one execution, so it is what makes a Run unique.
  temporal_workflow_id text        NOT NULL,
  temporal_run_id      text        UNIQUE,
  status               text        NOT NULL DEFAULT 'pending' CHECK (status IN (
                         'pending', 'running', 'succeeded', 'failed', 'canceled')),
  loop_counts          jsonb       NOT NULL DEFAULT '{}',
  started_at           timestamptz,
  finished_at          timestamptz,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now()
);

-- At most one active Run per Issue; a retry creates a new Run after the old one ends.
CREATE UNIQUE INDEX runs_one_active_per_issue_idx ON runs (issue_id) WHERE status IN ('pending', 'running');

CREATE TABLE step_runs (
  id          uuid        PRIMARY KEY,
  run_id      uuid        NOT NULL REFERENCES runs (id),
  step_id     text        NOT NULL,
  attempt     integer     NOT NULL CHECK (attempt >= 1),
  kind        text        NOT NULL CHECK (kind IN ('agent', 'gate', 'action', 'parallel')),
  status      text        NOT NULL DEFAULT 'pending' CHECK (status IN (
                'pending', 'running', 'succeeded', 'failed', 'canceled')),
  pod_name    text,
  commit_sha  text,
  -- An agent session's model usage (D53): cost as the LLM gateway recorded
  -- it for the session's key, tokens as the harness reported them.
  cost_usd      double precision NOT NULL DEFAULT 0 CHECK (cost_usd >= 0),
  input_tokens  bigint           NOT NULL DEFAULT 0 CHECK (input_tokens >= 0),
  output_tokens bigint           NOT NULL DEFAULT 0 CHECK (output_tokens >= 0),
  started_at  timestamptz,
  finished_at timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT step_runs_run_step_attempt_key UNIQUE (run_id, step_id, attempt)
);

-- Append-only. seq gives a strict total order for streaming and replay (FR-OB-2).
CREATE TABLE events (
  id          uuid        PRIMARY KEY,
  seq         bigint      NOT NULL GENERATED ALWAYS AS IDENTITY UNIQUE,
  run_id      uuid        REFERENCES runs (id),
  step_run_id uuid        REFERENCES step_runs (id),
  session_id  uuid,
  ts          timestamptz NOT NULL,
  type        text        NOT NULL,
  payload     jsonb       NOT NULL DEFAULT '{}',
  created_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX events_run_seq_idx ON events (run_id, seq);

-- A change request (PR/MR) opened for an issue's branch; neutral across providers (D12).
CREATE TABLE change_requests (
  id           uuid        PRIMARY KEY,
  issue_id     uuid        NOT NULL REFERENCES issues (id),
  run_id       uuid        NOT NULL REFERENCES runs (id),
  repo         text        NOT NULL,
  number       integer     NOT NULL,
  provider_ref text        NOT NULL,
  branch       text        NOT NULL,
  head_sha     text        NOT NULL,
  status       text        NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'merged', 'closed')),
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT change_requests_repo_number_key UNIQUE (repo, number)
);

-- The outcome of one gate StepRun (docs/spec/02, GateResult). The commit it
-- judged is the StepRun's commit_sha. One result per gate StepRun; a loop back
-- (M3) creates a new StepRun attempt.
CREATE TABLE gate_results (
  id          uuid        PRIMARY KEY,
  step_run_id uuid        NOT NULL REFERENCES step_runs (id),
  gate_type   text        NOT NULL CHECK (gate_type IN ('command', 'agent-verdict', 'human')),
  policy      text        NOT NULL CHECK (policy IN ('blocking', 'advisory')),
  verdict     text        NOT NULL CHECK (verdict IN ('pass', 'fail', 'escalated')),
  details     jsonb       NOT NULL DEFAULT '{}',
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT gate_results_step_run_key UNIQUE (step_run_id)
);

-- A decision a human gate waits for (docs/spec/03: human gates are Signals).
-- The workflow writes it when the gate opens and when it closes; the API only
-- reads it and signals the workflow, so the workflow stays the single writer.
CREATE TABLE approvals (
  id                 uuid        PRIMARY KEY,
  step_run_id        uuid        NOT NULL REFERENCES step_runs (id),
  run_id             uuid        NOT NULL REFERENCES runs (id),
  reason             text        NOT NULL,
  commit_sha         text,
  change_request_url text,
  status             text        NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'approved', 'rejected', 'timed_out')),
  decided_by         text,
  comment            text,
  expires_at         timestamptz NOT NULL,
  decided_at         timestamptz,
  created_at         timestamptz NOT NULL DEFAULT now(),
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT approvals_step_run_key UNIQUE (step_run_id)
);

CREATE INDEX approvals_status_idx ON approvals (status, created_at);

-- Questions an agent asked a person with the ask-human tool (D55): the
-- session's activity writes one when it sees the question event, the
-- InterveneSession activity records its answer, and finishing the step run
-- expires the ones nobody answered. question_id is the runner's.
CREATE TABLE questions (
  id          uuid        PRIMARY KEY,
  step_run_id uuid        NOT NULL REFERENCES step_runs (id),
  run_id      uuid        NOT NULL REFERENCES runs (id),
  question_id text        NOT NULL,
  question    text        NOT NULL,
  status      text        NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'answered', 'expired')),
  answer      text,
  answered_by text,
  answered_at timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT questions_step_run_question_key UNIQUE (step_run_id, question_id)
);

CREATE INDEX questions_status_idx ON questions (status, created_at);

-- The digest each toolchain image was built as (open question 15, D45). Pods
-- run toolchain images by this digest only: the registry is writable by build
-- pods, so a tag there proves nothing.
CREATE TABLE toolchain_images (
  repository text        NOT NULL,
  tag        text        NOT NULL,
  digest     text        NOT NULL CHECK (digest ~ '^sha256:[0-9a-f]{64}$'),
  built_at   timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (repository, tag)
);
